#!/usr/bin/env node
// Builds the dependency-free skill tool bundle from compiled dist/ output (run after `tsc`).
// Skills and Claude Code plugins install from git, where dist/ is not committed, so the bundle is committed.
//
// Usage: node scripts/build-skill-tools.mjs [--out <dir>]
//   Default output: skills/prompt-optimize/scripts
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, join, relative, resolve, sep } from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";

const rootPath = resolve(fileURLToPath(new URL("../", import.meta.url)));
const distPath = join(rootPath, "dist");
const ENTRY_MODULE = join(distPath, "cli", "harness-main.js");
const ENTRY_FILE = "arc-prompt-tools.mjs";
const LIB_DIR = "lib";

// Matches static `import`/`export ... from "x"`, side-effect `import "x"`, and dynamic `import("x")` specifiers.
const SPECIFIER = /(\bfrom\s*|\bimport\s*\(\s*|\bimport\s+)(["'])([^"']+)\2/gu;
const SOURCE_MAP_COMMENT = /\n?\/\/# sourceMappingURL=\S+\s*$/u;

const ENTRY_SOURCE = `#!/usr/bin/env node
// Generated by scripts/build-skill-tools.mjs from src/cli/harness-main.ts. Do not edit by hand.
// Model-free arc-prompt tools (candidates, score) with no npm dependencies. Requires Node.js >=22.19.
import { runHarnessCli } from "./${LIB_DIR}/cli/harness-main.mjs";

process.exitCode = await runHarnessCli();
`;

function parseOutDir(argv) {
  const index = argv.indexOf("--out");
  if (index === -1) return join(rootPath, "skills", "prompt-optimize", "scripts");
  const value = argv[index + 1];
  if (value === undefined) throw new Error("--out requires a directory.");
  return resolve(value);
}

function toMjs(path) {
  return path.replace(/\.js$/u, ".mjs");
}

/** Collects the relative import closure of the entry module; rejects any package import other than node: builtins. */
async function collectModules(entry) {
  const modules = new Map();
  const pending = [entry];
  while (pending.length > 0) {
    const file = pending.pop();
    if (modules.has(file)) continue;
    const source = await readFile(file, "utf8");
    const rewritten = source.replace(SOURCE_MAP_COMMENT, "\n").replace(SPECIFIER, (match, prefix, quote, specifier) => {
      if (specifier.startsWith("node:")) return match;
      if (!specifier.startsWith("./") && !specifier.startsWith("../")) {
        throw new Error(`${relative(rootPath, file)} imports package '${specifier}'; the skill tool bundle must be dependency-free.`);
      }
      if (!specifier.endsWith(".js")) throw new Error(`${relative(rootPath, file)} imports '${specifier}' without a .js extension.`);
      pending.push(resolve(dirname(file), specifier));
      return `${prefix}${quote}${toMjs(specifier)}${quote}`;
    });
    modules.set(file, rewritten);
  }
  return modules;
}

export async function buildSkillTools(outDir) {
  const modules = await collectModules(ENTRY_MODULE);
  const libPath = join(outDir, LIB_DIR);
  await rm(libPath, { recursive: true, force: true });
  const written = [ENTRY_FILE];
  for (const [file, source] of [...modules].sort(([a], [b]) => a.localeCompare(b))) {
    const relativePath = toMjs(relative(distPath, file));
    if (relativePath.startsWith("..")) throw new Error(`Module ${file} is outside dist/.`);
    const target = join(libPath, relativePath);
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, source);
    written.push([LIB_DIR, ...relativePath.split(sep)].join("/"));
  }
  await mkdir(outDir, { recursive: true });
  await writeFile(join(outDir, ENTRY_FILE), ENTRY_SOURCE, { mode: 0o755 });
  return written;
}

if (process.argv[1] !== undefined && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const outDir = parseOutDir(process.argv.slice(2));
  const written = await buildSkillTools(outDir);
  process.stdout.write(`Built ${written.length} skill tool files in ${relative(process.cwd(), outDir) || "."}\n`);
}
